    *s = (struct lwan_strbuf) {
        .flags = STATIC | DYNAMICALLY_ALLOCATED,
        .value.static_buffer = str,
        .used = size
    };

    return s;
}

void lwan_strbuf_free(struct lwan_strbuf *s)
{
    if (UNLIKELY(!s))
        return;
    if (!(s->flags & STATIC))
        free(s->value.buffer);
    if (s->flags & DYNAMICALLY_ALLOCATED)
