    memcpy(s1->value.buffer + s1->used, s2, sz);
    s1->used += sz;
    s1->value.buffer[s1->used] = '\0';

    return true;
}

bool lwan_strbuf_set_static(struct lwan_strbuf *s1, const char *s2, size_t sz)
{
    if (!sz)
